def top_cities(answers, n):
    # 1. clean each answer and keep the non-empty ones
    cities = []
    for answer in answers:
        city = answer.strip().lower()
        if city:
            cities.append(city)

    # 2. count each city
    counts = {}
    for city in cities:
        counts[city] = counts.get(city, 0) + 1

    # 3. sort: biggest count first, then A to Z
    ranked = sorted(counts.items(), key=lambda p: (-p[1], p[0]))

    # 4. keep the first n
    return ranked[:n]

def top_domains(emails, n):
    # 1. clean each email and keep the domain (the part after @)
    domains = []
    for email in emails:
        email = email.strip().lower()
        if email:
            domain = email.split("@")[1]
            domains.append(domain)

    # 2. count each domain
    counts = {}
    for domain in domains:
        counts[domain] = counts.get(domain, 0) + 1

    # 3. sort: biggest count first, then A to Z
    ranked = sorted(counts.items(), key=lambda p: (-p[1], p[0]))

    # 4. keep the first n
    return ranked[:n]

def top_items(data, n, chars=".,!?;: ", upper=False):
    # 1. string or list? Make sure we end up with a list
    if isinstance(data, str):
        raw_items = data.split()
    else:
        raw_items = data

    # 2. clean each item and keep the non-empty ones
    items = []
    for item in raw_items:
        item = item.strip(chars)
        if upper:
            item = item.upper()
        else:
            item = item.lower()
        if item:
            items.append(item)

    # 3. count each item
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1

    # 4. sort: biggest count first, then A to Z
    ranked = sorted(counts.items(), key=lambda p: (-p[1], p[0]))

    # 5. keep the first n
    return ranked[:n]

