def label(*names, **attrs):
    first = ', '.join(names) if names else 'nobody'
    return first + ' | ' + ', '.join(f'{k}={v}' for k, v in attrs.items())

def build_url(base, *path, **params):
    url = base
    for part in path:
        url += "/" + str(part)
    pairs = [f"{k}={v}" for k, v in params.items() if v is not None]
    if pairs:
        url += "?" + "&".join(pairs)
    return url

def log_line(level, *tags, **fields):
    parts = [f"[{level}]"] + list(tags)
    for k, v in fields.items():
        parts.append(f"{k}='{v}'" if isinstance(v, str) else f"{k}={v}")
    return " ".join(parts)

def count_query(table, *group_cols, **filters):
    cols = ", ".join(group_cols)
    select = f"{cols}, COUNT(*)" if group_cols else "COUNT(*)"
    sql = f"SELECT {select} FROM {table}"
    if filters:
        conds = [f"{k} = '{v}'" if isinstance(v, str) else f"{k} = {v}" for k, v in filters.items()]
        sql += " WHERE " + " AND ".join(conds)
    if group_cols:
        sql += " GROUP BY " + cols
    return sql

