def standardize(X):
    X = np.asarray(X, dtype=float)
    mu = X.mean(axis=0)
    sd = X.std(axis=0)
    safe = np.where(sd == 0, 1.0, sd)
    return np.where(sd == 0, 0.0, (X - mu) / safe)


def flag_outliers(X, z):
    return np.abs(standardize(X)) > z

