def top_orders(df, region, n):
    out = df.loc[df["region"] == region, ["order_id", "product", "units", "price"]].copy()
    out["revenue"] = out["units"] * out["price"]
    out = out.sort_values(["revenue", "order_id"], ascending=[False, True])
    return out[["order_id", "product", "revenue"]].head(n).reset_index(drop=True)

