def longest_unique_text(s):
    last = {}
    start = best_start = best_len = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        if i - start + 1 > best_len:
            best_len = i - start + 1
            best_start = start
    return s[best_start:best_start + best_len]

def longest_new_cities(trip):
